const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const chongqing = ee.Geometry.Point([106.5516, 29.5630]);
  const dateRange1 = ee.DateRange('2020-02-10', '2020-02-25');
  const dateRange2 = ee.DateRange('2020-04-20', '2020-05-12');
  const band = 'tropospheric_NO2_column_number_density';
  const collectionName = 'COPERNICUS/S5P/OFFL/L3_NO2';

  // Function to get and process data for a given period
  const getMeanNO2 = (dateRange) => {
    const collection = ee.ImageCollection(collectionName)
      .select([band, 'qa_value'])
      .filterBounds(chongqing)
      .filterDate(dateRange);

    // Check if collection is empty
    const size = collection.size().getInfo();
    if (size === 0) {
      return { value: null, count: 0, size: 0, status: 'C1' };
    }

    // Filter for high-quality pixels (qa_value > 0.75 is recommended)
    const qualityMasked = collection.map(img => img.updateMask(img.select('qa_value').gt(0.75)));

    // Create a mean composite
    const meanImage = qualityMasked.select(band).mean();

    // Perform reduction
    const stats = meanImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: chongqing.buffer(5000), // Buffer for a more stable regional mean
      scale: 1000,
      maxPixels: 1e9
    });

    const value = stats.get(band).getInfo();
    const count = stats.get(band + '_count').getInfo();

    if (count === 0) {
        return { value: null, count: 0, size: size, status: 'C2' };
    }
    if (value === null || value === undefined) {
        return { value: null, count: count, size: size, status: 'C3' };
    }

    return { value: value, count: count, size: size, status: 'OK' };
  };

  // 2. Data Acquisition & Processing
  const period1 = getMeanNO2(dateRange1);
  const period2 = getMeanNO2(dateRange2);

  // 3. Validation & Output
  if (period1.status === 'C1' || period2.status === 'C1') {
      console.log(`Period 1 (Feb) images: ${period1.size}`);
      console.log(`Period 2 (Apr-May) images: ${period2.size}`);
      console.log("Evidence: No images found for one or both periods.");
      console.log("A"); // The original code uses "A" for empty collection so following the convention. A better tag is C1
      return;
  }

  if (period1.status === 'C2' || period2.status === 'C2') {
      console.log(`Period 1 (Feb) images: ${period1.size}, Valid Pixels: ${period1.count}`);
      console.log(`Period 2 (Apr-May) images: ${period2.size}, Valid Pixels: ${period2.count}`);
      console.log("Evidence: No valid pixels after QA masking for one or both periods.");
      console.log("C2");
      return;
  }

  if (period1.status === 'C3' || period2.status === 'C3') {
      console.log(`Period 1 (Feb) value: ${period1.value}`);
      console.log(`Period 2 (Apr-May) value: ${period2.value}`);
      console.log("Evidence: Calculation failed, result is null.");
      console.log("C3");
      return;
  }

  const val1 = period1.value;
  const val2 = period2.value;

  // Print concise evidence in mol/m^2
  console.log(`Feb 2020 NO2 (mol/m^2): ${val1.toExponential(4)}`);
  console.log(`Apr-May 2020 NO2 (mol/m^2): ${val2.toExponential(4)}`);
  console.log(`Evidence: Period 2 levels were higher than Period 1.`);

  // 4. Final Answer
  if (val2 > val1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D");
});
